def need(ok,message):
    if not ok:raise RuntimeError(message)


def sha(data):return hashlib.sha256(data).hexdigest()


def read(path,limit=2*1024**2):
    path=Path(path)
    need(path.is_absolute() and path.is_relative_to(ROOT) and path.resolve(strict=True)==path,'Unexpected input path')
    fd=os.open(path,os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
    with os.fdopen(fd,'rb') as stream:
        m=os.fstat(stream.fileno())
        need(stat.S_ISREG(m.st_mode) and m.st_uid==1204 and m.st_size<=limit,'Unexpected input owner/type/size')
        data=stream.read(limit+1);n=os.fstat(stream.fileno())
        need((m.st_ino,m.st_size,m.st_mtime_ns,m.st_ctime_ns)==(n.st_ino,n.st_size,n.st_mtime_ns,n.st_ctime_ns),'Input changed')
    return data


def load(path):return json.loads(read(path))


def validate_candidate(name,data):
    row=CORE_ARTIFACTS[name]
    need(len(data)==row['bytes'] and sha(data)==row['sha256'],'Native candidate hash differs: '+name)
    need(data[:4]==b'\x7fELF' and data[4:6]==b'\x02\x01'
         and int.from_bytes(data[18:20],'little')==183,'Expected ARM64 ELF: '+name)


def candidate_artifacts(n):
    paths={'server':OLD_DEPLOY/'bin/server'}
    if n=='a':
        report=load(ROOT/'builds/ub-private-delete-daemon-resume-v2/return.json')
        need(report['status']=='UB_PRIVATE_DELETE_DAEMON_BUILT_TESTED_NOT_DEPLOYED'
             and report['release']['coreCommit']==CORE_COMMIT
             and report['nativePrivateRegistryTestsPassed'] is True
             and report['rebuiltComponents']==['uvm-ublk-daemon']
             and report['fullPreserved'] is True
             and report['artifacts']['uvm-ublk-daemon']==CORE_ARTIFACTS['uvm-ublk-daemon']
             and all(report.get(k) is False for k in ('SDK_called','Guest_created','servicesChanged','kernelChanged')),
             'Native hotfix daemon build evidence differs')
        paths['uvm-ublk-daemon']=Path(CORE_ARTIFACTS['uvm-ublk-daemon']['path'])
    else:
        paths['uvm-ublk-daemon']=ROOT/'uvm-ublk-daemon-private-delete-v1'
    for name,path in paths.items():validate_candidate(name,read(path,128*1024**2))
    return paths


def package_candidates(paths):
    # Only the new daemon needs human transfer; B already has the identical server.
    path=paths['uvm-ublk-daemon'];raw=read(path,128*1024**2);validate_candidate('uvm-ublk-daemon',raw)
    return {'path':str(path),'bytes':len(raw),'sha256':sha(raw),
            'destinationOnB':str(ROOT/'uvm-ublk-daemon-private-delete-v1'),
            'contents':'only fixed daemon; manual transfer, no new transport provisioned'}


def node():return {'server1':'a','agent1':'b'}[platform.node()]


