def check_provider(n):
    work=ROOT/'r'/('uf-'+n+'-v1')
    state=load(work/'p/owner.json');process=load(work/'provider-process.json')
    need(state['state']=='serving' and state['ownerId']==OWNER and state['manifestSha256']==MANIFEST,'Provider generation not serving')
    need(process['bootId']==Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'Provider boot changed')
    need(Path('/proc/'+str(process['pid'])+'/stat').read_text().rsplit(')',1)[1].split()[19]==process['startTicks'],'Provider PID changed')
    index=load(work/'p/runtime-index.json')
    need(index['version']==1 and index['state']=='ready' and len(index['replicas'])==8
         and all(r['allowRepositoryFallback'] is False for r in index['replicas']),'Required rootfs index invalid')
    return {'path':str(work/'p/runtime-index.json'),'sha256':sha(read(work/'p/runtime-index.json')),
            'ownerId':OWNER,'manifestSha256':MANIFEST,'providerProcess':process}


def make_module(definition):
    raw=base64.b64decode(BASE_SOURCE_B64,validate=True)
    need(sha(raw)==BASE_SOURCE_SHA,'Audited launch library differs')
    m=types.ModuleType('direct_guest_audited');m.__file__=str(D/'libexec/audited_base.py')
    exec(compile(raw,m.__file__,'exec'),m.__dict__)
    n=definition['node'];need(n in ('a','b') and definition['apiPort'] in range(18085,18090),'Deployment node/port invalid')
    need(definition['ub']['path']==str(ROOT/'r'/('uf-'+n+'-v1')/'p/runtime-index.json')
         and re.fullmatch('[0-9a-f]{64}',definition['ub']['sha256']),'Unexpected provider index')
    runtime,fc,unit=location(n)
    m.D=D;m.RUNTIME=runtime;m.UNIT=unit;m.PORT=definition['apiPort']
    m.BASE=ROOT/'deployments/agentenv-ae9c626-baseline'
    m.OLD_UNIT='jwk-aenv-ae9c626-node-'+n+'.service'
    m.NODE='node-'+n;m.EXPECTED_HOST='server1' if n=='a' else 'agent1'
    m.BINARIES=BINARIES;m.REVISION='aenv-direct-ub-deletefix-v1';m.STATUS_PREFIX='DIRECT_UB_GUEST'
    m.COMMIT=CORE_COMMIT
    m.LAUNCHER=D/'libexec/direct_guest_runtime.py';m.config_text=lambda:config(n,definition['ub'])
    # Keep CLI credentials and PATH helpers entirely inside the new deployment.
    # The older library's cli_files writes a historical shared activation file.
    def cli_files(key):
        cli=D/'cli'
        for path in (cli/'cache',cli/'tmp'):m.mkdir(path)
        wrapper=('#!/bin/sh\nexport XDG_CONFIG_HOME="'+str(cli/'config')+'"\n'
                 'export XDG_CACHE_HOME="'+str(cli/'cache')+'"\n'
                 'export TMPDIR="'+str(cli/'tmp')+'"\n'
                 'export LD_LIBRARY_PATH="'+str(D/'native/lib')+':'+str(D/'native/fallback/lib')+'"\n'
                 'unset http_proxy https_proxy HTTP_PROXY HTTPS_PROXY all_proxy ALL_PROXY\n'
                 'export NO_PROXY="127.0.0.1,localhost,::1"\nexport no_proxy="$NO_PROXY"\n'
                 'exec "'+str(D/'bin/aenv')+'" "$@"\n')
        m.put(cli/'bin/aenv-ub',wrapper.encode(),0o700)
        m.put(cli/'config/aenv/credentials',('url = "http://127.0.0.1:'+str(definition['apiPort'])+'"\napi_key = '+json.dumps(key)+'\n').encode())
    m.cli_files=cli_files
    original=m.environment
    def environment():
        env=original()
        need(sha(read(definition['ub']['path']))==definition['ub']['sha256'],'UB index changed')
        check_provider(n)
        need('AENV_UB_ROOTFS_REPLICAS' not in env,'Unexpected environment binding')
        need('AENV_DIRECT_ROOTFS_BINDING' not in env and 'AENV_UB_MEMORY_REPLICAS' not in env,'Wrong scope')
        return env
    m.environment=environment
    return m


def preserve_units(m,n):
    result={}
    for unit in ('jwk-aenv-ae9c626-node-'+n+'.service','jwk-aenv-lazy-four-32ce41c-node-'+n+'.service',
                 'jwk-aenv-dsec-hostfile-v1-node-'+n+'.service','ubsmd.service','ubse.service'):
        fields=m.properties(unit);pid=int(fields.get('MainPID','0'))
        ticks=Path('/proc/'+str(pid)+'/stat').read_text().rsplit(')',1)[1].split()[19] if pid>1 else None
        result[unit]=[fields.get('LoadState'),fields.get('ActiveState'),pid,ticks]
    return result


def choose_port():
    port=load(OLD_DEPLOY/'guest-definition.json')['apiPort']
    need(port in range(18085,18090),'Old dedicated port differs')
    # Reuse the same loopback API port after verified old-unit/proxy shutdown.
    # Never choose or open an additional port as a workaround.
    with socket.socket() as stream:stream.bind(('127.0.0.1',port))
    return port


def prepare():
    n=node();need(sys.platform=='linux' and platform.machine()=='aarch64','Native ARM64 required')
    need(os.getuid()==os.geteuid()==1204 and os.getgid()==os.getegid()==1205,'Use ordinary jwk')
    source=load(SOURCE/'definition-native.json')
    need(sha(read(SOURCE/'definition-native.json'))==SOURCE_DEFINITION[n] and not source.get('rootfsBinding'),
         'Retained ordinary deployment definition changed')
    need(all(source['binaries'][k]==v for k,v in OLD_BINARIES.items()),'Retained binary set differs')
    candidates=candidate_artifacts(n)
    definition={'version':1,'node':n,'apiPort':choose_port(),'ub':check_provider(n),'templateId':TEMPLATE,
                'catalogSha256':CATALOG_SHA,'coreCommit':CORE_COMMIT,'serverBuildSourceCommit':SERVER_BUILD_COMMIT,'daemonBuildSourceCommit':CORE_COMMIT,'binaries':BINARIES,'rootfsBinding':'required-ub-stored-lower'}
    m=make_module(definition);m.identity();m.no_caps()
    runtime,fc,unit=location(n)
    for path in (D,runtime,fc):need(path.resolve()==path and not path.exists() and not path.is_symlink(),'New path already exists; preserve it')
    old=preserve_units(m,n)
    source_repo=SOURCE/'state/snapshot-store/repository'
    record_raw=read(source_repo/'catalog/records'/(TEMPLATE+'.json'))
    need(sha(record_raw)==CATALOG_SHA,'Retained template record differs')
    record=json.loads(record_raw);manifest=load(source_repo/'snapshots'/TEMPLATE/'firecracker-manifest.json')
    need(record['resources'].get('cpu_count')==2 and record['resources'].get('memory_mib')==4096,
         'Template resources differ')
    need(not manifest.get('nativeRootfs') and not manifest.get('attachedDrives')
         and manifest['memory']['virtualSize']==4096*1024**2,'Only ordinary retained rootfs/memory supported')
    committed=record['committed']
    need(not any(committed.get(k) for k in ('attached_drives','volume_snapshots','memory_startup')),'Unsupported snapshot dependencies')
    roots=[x['Managed'] for x in committed['rootfs_layers']]
    idx=load(definition['ub']['path'])
    need(sorted((x['digest'],x['size']) for x in roots)==sorted((x['layerDigest'],x['fileBytes']) for x in idx['replicas']),
         'Retained template does not exactly match the current eight UB objects')
    need(read(source_repo/'snapshots'/TEMPLATE/'commit')==b'committed','Snapshot commit marker differs')
    for row in roots+committed['memory_layers']:
        need(re.fullmatch('sha256:[0-9a-f]{64}',row['digest']) and type(row['size']) is int and row['size']>0,
             'Invalid immutable layer identity')
        path=source_repo/'managed-layers'/(row['digest'].replace(':','_')+'.overlaybd.commit')
        need(path.resolve(strict=True)==path and path.is_file() and path.stat().st_uid==1204
             and path.stat().st_size==row['size'],'Retained immutable layer changed')
    input_manifest=load(SOURCE/'input-manifest.json')
    def selected_inputs():
        result=[]
        for relative,row in sorted(input_manifest.items()):
            need(not Path(relative).is_absolute() and '..' not in Path(relative).parts,'Invalid retained input name')
            if not relative.startswith(('native/','deps/')) and relative not in ('bin/'+k for k in BINARIES):continue
            path=SOURCE/relative;data,meta=m.stable_file(path)
            need(sha(data)==row['sha256'],'Retained immutable dependency changed: '+relative)
            result.append((Path(relative),path,0o750 if meta.st_mode & 0o111 else 0o640,row['sha256']))
        result=[x for x in result if x[0].as_posix() not in ('bin/server','bin/uvm-ublk-daemon')]
        for name,path in candidates.items():result.append((Path('bin')/name,path,0o750,BINARIES[name]))
        names={x[0].as_posix() for x in result}
        need(all('bin/'+x in names for x in BINARIES) and len(result)<=2048,'Incomplete or oversized dependency set')
        need(sum(x[1].stat().st_size for x in result)<=3*1024**3,'Dependency budget exceeded')
        return result
    m.selected_inputs=selected_inputs
    entry_raw=Path(__file__).read_bytes()
    def stage_launcher():
        m.put(m.LAUNCHER,entry_raw)
        m.dump(D/'guest-definition.json',definition)
        return {}
    m.stage_launcher=stage_launcher
    result=m.install()
    trace_dir=D/'logs/rootfs-access';trace_dir.mkdir(mode=0o700)
    for name in ('server','uvm-ublk-daemon'):
        spec='output='+str(trace_dir/(name+'-{pid}.jsonl'))+'\nmax_bytes=67108864\nmax_records=500000\n'
        spec+=''.join('allow_content='+r['layerDigest']+':'+str(r['fileBytes'])+'\n' for r in idx['replicas'])
        m.put((D/'bin'/name).with_suffix('.access-spec'),spec.encode())
    repository=D/'state/snapshot-store/repository'
    for path in (repository/'catalog/records',repository/'managed-layers',repository/'snapshots'/TEMPLATE,
                 fc,D/'logs/firecracker'):
        path.mkdir(parents=True,exist_ok=True,mode=0o700)
    m.put(repository/'catalog/records'/(TEMPLATE+'.json'),record_raw)
    m.dump(D/'guest-cohort-state.json',{'version':1,'phase':'prepared','openRequests':[],
                                      'sandboxIds':[],'outcomeUncertain':False})
    need(preserve_units(m,n)==old,'An existing service changed during preparation')
    pins={str(D/name):row['sha256'] for name,row in load(D/'input-manifest.json').items()}
    for name in ('guest-definition.json','config/runtime.toml','config/api-key','installation.json',
                 'libexec/direct_guest_runtime.py','guest-cohort-state.json','bin/server.access-spec','bin/uvm-ublk-daemon.access-spec',
                 'cli/bin/aenv-ub','cli/config/aenv/credentials',
                 'state/snapshot-store/repository/catalog/records/'+TEMPLATE+'.json'):
        pins[str(D/name)]=sha(read(D/name))
    review={'node':n,'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
            'unit':unit,'port':definition['apiPort'],'pins':pins,'preserveUnits':old,
            'launcher':str(m.LAUNCHER),'launcherSha256':sha(entry_raw),'provider':definition['ub'],
            'readonlyMounts':[{'source':str(source_repo/'managed-layers'),'target':str(repository/'managed-layers')},
                              {'source':str(source_repo/'snapshots'/TEMPLATE),'target':str(repository/'snapshots'/TEMPLATE)}]}
    m.dump(D/'activation-review.json',review)
    package=package_candidates(candidates) if n=='a' else None
    result.update(status='DIRECT_GUEST_RUNTIME_PREPARED_NOT_STARTED',coreCommit=CORE_COMMIT,binaries=BINARIES,transferPackage=package,templateId=TEMPLATE,
                  existingServicesUnchanged=True,SDK_called=False,Guest_created=False,
                  largeSnapshotPayloadCopied=False,activationReview=str(D/'activation-review.json'),
                  next='Activate only this new unit from the verified root entry; then health and owned Guest test')
    result['next_action']='Use the pinned root activation entry for this new unit; no Guest has been started'
    m.dump(D/'prepare-report.json',result)
    return result


def readonly_mounts(m,definition):
    receipt=m.installed()
    need(int(m.properties(m.UNIT).get('MainPID',0))==os.getpid(),'Not the reviewed unit main process')
    need(os.stat('/proc/self/ns/mnt').st_ino!=receipt['host_mntns']
         and os.stat('/proc/self/ns/net').st_ino!=receipt['host_netns'],'Private mount/network namespaces required')
    need(all(m.caps().get(k,0)==m.CAPS for k in ('CapInh','CapPrm','CapEff','CapAmb')),'Startup capabilities differ')
    review=load(D/'activation-review.json')
    expected=[(SOURCE/'state/snapshot-store/repository/managed-layers',D/'state/snapshot-store/repository/managed-layers'),
              (SOURCE/'state/snapshot-store/repository/snapshots'/TEMPLATE,D/'state/snapshot-store/repository/snapshots'/TEMPLATE)]
    need(review['readonlyMounts']==[{'source':str(a),'target':str(b)} for a,b in expected],'Mount plan changed')
    for source,target in expected:
        need(source.resolve(strict=True)==source and target.resolve(strict=True)==target
             and source.is_dir() and target.is_dir(),'Redirected mount source or target')
        subprocess.run(['/usr/bin/mount','--bind',str(source),str(target)],check=True,timeout=30)
        subprocess.run(['/usr/bin/mount','-o','remount,bind,ro',str(target)],check=True,timeout=30)
        rows=[line.split() for line in Path('/proc/self/mountinfo').read_text().splitlines() if line.split()[4]==str(target)]
        need(len(rows)==1 and 'ro' in rows[0][5].split(','),'Readonly bind not confirmed; do not start Runtime')


def activate():
    n=node();need(os.geteuid()==0,'Activation requires reviewed root execution')
    review=load(D/'activation-review.json');definition=load(D/'guest-definition.json');m=make_module(definition)
    need(review['node']==n and review['bootId']==Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'Activation node/boot differs')
    need(review['unit']==location(n)[2] and review['launcher']==str(D/'libexec/direct_guest_runtime.py'),'Activation scope differs')
    need(definition['node']==n and definition['apiPort']==review['port']
         and definition['coreCommit']==CORE_COMMIT and definition['binaries']==BINARIES,'Deployment definition differs')
    need(preserve_units(m,n)==review['preserveUnits'],'An existing service changed; do not activate')
    need(m.properties(review['unit']).get('LoadState')=='not-found','New unit already exists; do not repeat activation')
    need(sha(Path(__file__).read_bytes())==review['launcherSha256'],'Activation entry differs')
    for name,pin in review['pins'].items():need(sha(read(name,512*1024**2))==pin,'Reviewed input changed')
    need(check_provider(n)==review['provider'],'Provider generation or identity changed')
    with socket.socket() as stream:stream.bind(('127.0.0.1',review['port']))
    command=['/usr/bin/systemd-run','--unit='+review['unit'],'--collect',
        '--property=Description=AgentENV direct UB one Guest validation','--property=User=jwk','--property=Group=jwk',
        '--property=SupplementaryGroups=kvm aenv','--property=CapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN',
        '--property=AmbientCapabilities=CAP_SYS_ADMIN CAP_NET_ADMIN','--property=NoNewPrivileges=yes',
        '--property=RestrictSUIDSGID=yes','--property=PrivateNetwork=yes','--property=PrivateMounts=yes',
        '--property=Type=exec','--property=Restart=no','--property=KillMode=control-group',
        '--property=TimeoutStopSec=90s','--property=LimitNOFILE=65536','--property=LimitMEMLOCK=2147483648',
        '--property=WorkingDirectory='+str(D),'--property=StandardOutput=null','--property=StandardError=null',
        '/usr/bin/python3','-I','-B',str(m.LAUNCHER),'inside','--run']
    subprocess.run(command,check=True,timeout=30)
    return {'status':'DIRECT_GUEST_NEW_UNIT_SUBMITTED','unit':review['unit'],'Guest_created':False,'SDK_called':False}


def as_owner(command,timeout=180):
    return subprocess.run(['/usr/bin/setpriv','--reuid=1204','--regid=1205','--clear-groups',
        '--inh-caps=-all','--ambient-caps=-all','--bounding-set=-all','--no-new-privs',*command],
        env={'HOME':'/home/jwk','USER':'jwk','LOGNAME':'jwk','PATH':'/usr/bin:/bin','LANG':'C.UTF-8'},
        capture_output=True,text=True,timeout=timeout)


def stop_empty():
    n=node();need(os.geteuid()==0,'Use root for scoped empty-service stop')
    definition=load(D/'guest-definition.json');review=load(D/'activation-review.json');m=make_module(definition)
    need(review['bootId']==Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'Boot changed')
    m.installed()
    need(preserve_units(m,n)==review['preserveUnits'],'Existing service identities changed; preserve state')
    props=m.properties(m.UNIT);pid=int(props.get('MainPID','0'))
    need(props.get('ActiveState')=='active' and pid>1,'New service not active; retain failed startup evidence')
    actual=m.process_identity(pid);attestation=load(location(n)[0]/'runtime-attestation.json')
    need(actual['exe']==str(D/'bin/server') and actual['pid']==attestation['pid']
         and actual['start_ticks']==attestation['start_ticks'],'New service identity differs')
    result=as_owner([str(D/'cli/bin/aenv-ub'),'list','--output','json'],30)
    need(result.returncode==0 and json.loads(result.stdout)==[],
         'Guest inventory not confirmed empty; use Guest reconciliation, do not stop')
    # Available only before the Guest controller has recorded any request.
    cohort=load(D/'guest-cohort-state.json')
    need(cohort=={'version':1,'phase':'prepared','openRequests':[],'sandboxIds':[],'outcomeUncertain':False},
         'Guest operations may exist; empty inventory alone cannot authorize cleanup')
    need(m.properties(m.UNIT).get('MainPID')==str(pid) and m.process_identity(pid)['start_ticks']==actual['start_ticks'],
         'New service changed before stop')
    subprocess.run(['/usr/bin/systemctl','stop',m.UNIT],check=True,timeout=100)
    need(m.properties(m.UNIT).get('ActiveState') in ('inactive','failed')
         and int(m.properties(m.UNIT).get('MainPID','0'))==0,'New service stop not confirmed')
    proxy_path=location(n)[0]/'host-proxy.json'
    if proxy_path.exists():
        proxy=load(proxy_path)
        try:current=m.process_identity(proxy['pid'])
        except FileNotFoundError:current=None
        if current:
            need(current['uid']==[1204]*4 and current['start_ticks']==proxy['start_ticks']
                 and m.owns_listener(proxy['pid']),'Host proxy identity differs; do not signal')
            need(hasattr(os,'pidfd_open') and hasattr(signal,'pidfd_send_signal'),'No race-safe proxy stop support')
            fd=os.pidfd_open(proxy['pid'])
            try:
                need(m.process_identity(proxy['pid'])['start_ticks']==proxy['start_ticks'],'Proxy identity changed')
                signal.pidfd_send_signal(fd,signal.SIGTERM)
            finally:os.close(fd)
    need(preserve_units(m,n)==review['preserveUnits'],'Existing service changed during stop')
    return {'status':'DIRECT_GUEST_EMPTY_NEW_UNIT_STOPPED_DATA_PRESERVED','unit':m.UNIT,
            'providerStopped':False,'SDK_called':False,'kernelChanged':False,
            'scope':'Only new empty Runtime stopped; all logs, snapshots, UB objects and existing units preserved'}


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('mode',choices=('prepare','activate','stop-empty','inside','proxy-inside','proxy-host','health'))
    parser.add_argument('--run',action='store_true')
    args=parser.parse_args()
    if args.mode in ('prepare','activate','stop-empty') and not args.run:
        print(json.dumps({'status':'DIRECT_GUEST_PLAN_NO_ACTION','mode':args.mode,'deployment':str(D)}));return 0
    if args.mode=='prepare':result=prepare()
    elif args.mode=='activate':
        result=activate()
        checked=as_owner(['/usr/bin/python3','-I','-B',str(D/'libexec/direct_guest_runtime.py'),'health'])
        print(checked.stdout,flush=True)
        need(checked.returncode==0,'New service health failed; preserve logs and service, no automatic restart')
        result['ordinaryUserHealthPassed']=True
    elif args.mode=='stop-empty':result=stop_empty()
    else:
        definition=load(D/'guest-definition.json');m=make_module(definition);m.identity()
        if args.mode=='inside':readonly_mounts(m,definition);m.inside();return 0
        if args.mode.startswith('proxy-'):
            import asyncio
            asyncio.run(m.proxy(args.mode.split('-',1)[1]));return 0
        m.no_caps();before=preserve_units(m,node());result=m.health(False)
        need(preserve_units(m,node())==before,'Existing services changed during health')
        need(result['CLI_list_count']==0,'Expected empty new Runtime; preserve unexpected Guests')
        result.pop('activate',None)
        result.update(status='DIRECT_GUEST_RUNTIME_HEALTHY_NO_GUEST_YET',Guest_created=False,SDK_called=False,
                      UB_Guest_replicas_configured=True,coreCommit=CORE_COMMIT,binaries=BINARIES,
                      rootfsIndexSha256=definition['ub']['sha256'],daemonStartedAndAttested=False)
    print('BEGIN_DIRECT_GUEST_RUNTIME_REPORT');print(json.dumps(result,indent=2));print('END_DIRECT_GUEST_RUNTIME_REPORT')
    return 0


if __name__=='__main__':
    try:rc=main()
    except Exception as error:
        print(json.dumps({'status':'STOPPED_DIRECT_GUEST_RUNTIME_PRESERVE_OUTPUTS',
                          'errorType':type(error).__name__,'reason':str(error),'automaticRecovery':False}))
        rc=1
    raise SystemExit(rc)
